CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT NOT NULL,price REAL NOT NULL CHECK(price>=0),image_url TEXT,category TEXT NOT NULL,stock INTEGER NOT NULL CHECK(stock>=0),featured INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS cart_items(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL CHECK(quantity>0),UNIQUE(user_id,product_id));
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),total_amount REAL NOT NULL,customer_name TEXT NOT NULL,phone TEXT NOT NULL,shipping_address TEXT NOT NULL,payment_method TEXT NOT NULL DEFAULT 'Cash on Delivery',payment_status TEXT NOT NULL DEFAULT 'Pending',order_status TEXT NOT NULL DEFAULT 'Placed',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,product_id INTEGER REFERENCES products(id),product_name TEXT NOT NULL,unit_price REAL NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),subtotal REAL NOT NULL);
CREATE INDEX IF NOT EXISTS idx_prod_cat ON products(category);
CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id);
CREATE INDEX IF NOT EXISTS idx_items_order ON order_items(order_id);
